import json, os, time, urllib.request, urllib.error
M = "/home/ejb/Forge/apps/dossier/haiku-batch-manifest.json"
B = "http://127.0.0.1:8437"

def call(method, path, body=None, timeout=120):
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(B + path, data=data, method=method,
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        return e.code, {"detail": e.read().decode(errors="replace")[:300]}

def load():
    with open(M) as fh:
        return json.load(fh)

def save(m):
    tmp = M + ".tmp"
    with open(tmp, "w") as fh:
        json.dump(m, fh, indent=2, ensure_ascii=False)
    os.replace(tmp, M)

m = load()
done = failed = 0
for s in m["subjects"]:
    if s["fill_in"] != "pending":
        continue
    while call("GET", "/api/history")[1].get("running"):
        time.sleep(3)
    code, body = call("POST", "/api/subject/" + s["slug"] + "/new-info", {})
    if code != 200:
        s["fill_in"] = ("failed: %s %s" % (code, body.get("detail", "")))[:200]
        failed += 1
    else:
        time.sleep(2)
        state = call("GET", "/api/history")[1]
        while state.get("running"):
            time.sleep(3)
            state = call("GET", "/api/history")[1]
        s["fill_in"] = "done: +%s news items, article %s" % (
            state.get("events_added", 0),
            "refreshed" if state.get("articles_added") else "unchanged")
        done += 1
    save(m)
    print(s["name"], "->", s["fill_in"], flush=True)
print("fill in finished: %d done, %d failed this run" % (done, failed))

