import json, os, time, urllib.request, urllib.error
M = "/home/ejb/Forge/apps/dossier/haiku-batch-manifest.json"
B = "http://127.0.0.1:8437"

def call(method, path, body=None, timeout=120):
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(B + path, data=data, method=method,
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        return e.code, {"detail": e.read().decode(errors="replace")[:300]}

def load():
    with open(M) as fh:
        return json.load(fh)

def save(m):
    tmp = M + ".tmp"
    with open(tmp, "w") as fh:
        json.dump(m, fh, indent=2, ensure_ascii=False)
    os.replace(tmp, M)

m = load()
if m.get("queue_id"):
    code, body = call("POST", "/api/queues/" + m["queue_id"] + "/activate")
    if code != 200:
        raise SystemExit("could not re-activate queue %s: %s %s" % (m["queue_id"], code, body))
else:
    code, body = call("POST", "/api/queues", {"name": m["queue_name"], "redo_held": True, "activate": True})
    if code != 200:
        raise SystemExit("could not create the queue: %s %s" % (code, body))
    m["queue_id"] = body["queue"]["id"]
    save(m)
queued = 0
for s in m["subjects"]:
    if s["deep_dive"] != "pending":
        continue
    code, body = call("POST", "/api/research", {"name": s["name"], "entity_type": s["entity_type"], "qid": s["qid"], "phase": "deep"})
    if code == 200:
        s["deep_dive"] = "queued"
        s["job_id"] = body.get("id", "")
        queued += 1
    else:
        s["deep_dive"] = ("failed to queue: %s %s" % (code, body.get("detail", "")))[:200]
save(m)
state = call("GET", "/api/queue")[1]
print("queued %d; active queue %s; counts %s; workers %s; paused %s" % (
    queued, state["active_queue"]["name"], state["counts"], state["workers"], state["paused"]))

