import json, os, time, urllib.request, urllib.error
M = "/home/ejb/Forge/apps/dossier/haiku-batch-manifest.json"
B = "http://127.0.0.1:8437"

def call(method, path, body=None, timeout=120):
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(B + path, data=data, method=method,
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        return e.code, {"detail": e.read().decode(errors="replace")[:300]}

def load():
    with open(M) as fh:
        return json.load(fh)

def save(m):
    tmp = M + ".tmp"
    with open(tmp, "w") as fh:
        json.dump(m, fh, indent=2, ensure_ascii=False)
    os.replace(tmp, M)

m = load()
state = call("GET", "/api/queue")[1]
if state.get("active_queue", {}).get("id") != m.get("queue_id"):
    raise SystemExit("the active queue is not this batch's queue; nothing recorded")
jobs = {j["id"]: j for j in state.get("jobs", [])}
for s in m["subjects"]:
    j = jobs.get(s.get("job_id"))
    if not j:
        continue
    if j["status"] == "done":
        ch = j.get("changes") or {}
        s["deep_dive"] = "done: +%s claims, +%s sources, +%s events" % (
            ch.get("claims_added", 0), ch.get("sources_added", 0), ch.get("timeline_added", 0))
        if (j.get("report") or {}).get("claims_complete") is False:
            s["deep_dive"] += " (claims incomplete - see Failures on the Jobs tab)"
    elif j["status"] in ("failed", "skipped"):
        s["deep_dive"] = ("%s: %s" % (j["status"], j.get("error") or j.get("note", "")))[:200]
    else:
        s["deep_dive"] = j["status"]
m["last_checked"] = time.strftime("%Y-%m-%dT%H:%M:%S")
m["queue_counts"] = state.get("counts")
save(m)
print("counts:", state.get("counts"))
for s in m["subjects"]:
    if s["deep_dive"].startswith(("done", "failed", "skipped")):
        print(" ", s["name"], "->", s["deep_dive"])
print("failures listed by the queue:", len(state.get("errors") or []))
